python3 -c "
import os, glob
try:
    import pypdf
    def get_text(pdf_path):
        reader = pypdf.PdfReader(pdf_path)
        return ''.join([page.extract_text() or '' for page in reader.pages])
except ImportError:
    import subprocess
    def get_text(pdf_path):
        res = subprocess.run(['pdftotext', pdf_path, '-'], capture_output=True, text=True)
        return res.stdout

for pdf in glob.glob('/workspace/company_files/**/*.pdf', recursive=True):
    txt = get_text(pdf)
    if '4C' in txt or 'Mesa Vista' in txt or 'Mesa' in txt or 'Pete' in txt or 'Sunshine' in txt:
        print(f'=== {pdf} ===')
        print(txt[:500])
        print('\n')
"

