import glob, pypdf

for pdf in sorted(glob.glob('/workspace/company_files/**/*.pdf', recursive=True)):
    try:
        reader = pypdf.PdfReader(pdf)
        txt = ''.join([page.extract_text() or '' for page in reader.pages])
        if any(k in txt for k in ['4C', 'Mesa Vista', 'Mesa', 'Pete', 'Sunshine']):
            print(f'=== {pdf} ===')
            print(txt.strip())
            print('='*50)
    except Exception as e:
        print(f'Error reading {pdf}: {e}')
